def starts_one_ends(n):
    """
    Pozitif bir tam sayı n verildiğinde, 1 ile başlayan veya 1 ile biten
    n basamaklı pozitif tam sayıların sayısını döndür.
    """
    if n == 1:
        return 2  # 1 ve 10
    elif n == 2:
        return 18  # 10-19 ve 21, 31, ..., 91
