def f(n):
    """ n parametresini alan ve n boyutunda bir liste döndüren f fonksiyonunu uygula.
    Liste içinde i indeksindeki elemanın değeri, i çift sayı ise i'nin faktöriyeli,
    aksi takdirde 1'den i'ye kadar olan sayıların toplamı olmalıdır.
    i değeri 1'den başlar.
    i'nin faktöriyeli, 1'den i'ye kadar olan sayıların çarpımıdır (1 * 2 * ... * i).
    Örnek:
    f(5) == [1, 2, 6, 24, 15]
    """
    def factorial(x):
        """Verilen sayının faktöriyelini hesaplar."""
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    def sum_to_n(x):
        """Verilen sayının 1'den x'e kadar olan sayıların toplamını hesaplar."""
        return sum(range(1, x + 1))

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_n(i))
    return result
