def histogram(test):
    """Boşluklarla ayrılmış küçük harfleri temsil eden bir string verildiğinde, 
    en çok tekrar eden harfi ve karşılık gelen sayımı içeren bir sözlük döndür.
    Eğer birkaç harf aynı sayıda tekrar ediyorsa, hepsini döndür.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Boş bir string verildiğinde boş bir sözlük döndür
    if not test:
        return {}

    # Harfleri saymak için bir sözlük
    char_count = {}

    # Stringi küçük harflere çevirip boşlukları kaldır
    test = test.lower().replace(" ", "")

    # Harfleri say
    for char in test:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # En yüksek tekrar eden sayıyı bul
    max_count = max(char_count.values())

    # En yüksek tekrar eden harfleri içeren bir sözlük döndür
    result = {char: count for char, count in char_count.items() if count == max_count}

    return result
```

