def fix_spaces(text):
    """
    Verilen bir string text içindeki tüm boşlukları alt çizgi ile değiştir,
    ve eğer string 2'den fazla ardışık boşluk içeriyorsa,
    tüm ardışık boşlukları - ile değiştir

    fix_spaces("Example") == "Example"
    fix_spaces("Example 1") == "Example_1"
    fix_spaces(" Example 2") == "_Example_2"
    fix_spaces(" Example   3") == "_Example-3"
    """
    result = []
    space_count = 0

    for char in text:
        if char == " ":
            space_count += 1
        else:
            if space_count > 1:
                result.append('-')
            elif space_count == 1:
                result.append('_')
            space_count = 0
            result.append(char)

    if space_count > 1:
        result.append('-')
    elif space_count == 1:
        result.append('_')

    return ''.join(result)
```

