def solve(s):
    """Bir string s verilmiştir.
    Eğer s[i] bir harf ise, küçük harften büyük harfe veya tam tersi şekilde durumunu değiştir,
    aksi takdirde olduğu gibi bırak.
    Eğer string hiç harf içermiyorsa, string'i ters çevir.
    Fonksiyon sonuç string'i döndürmelidir.
    Örnekler
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    result = []
    has_letter = False

    for char in s:
        if char.isalpha():
            has_letter = True
            if char.islower():
                result.append(char.upper())
            else:
                result.append(char.lower())
        else:
            result.append(char)

    if not has_letter:
        return ''.join(result[::-1])
    else:
        return ''.join(result)
